insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e2fec21a-d1aa-4bf0-818b-23a84da817bb', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Psychology as a Science: History, Perspectives, and Big Questions', 'This opening unit frames psychology as a science that grew from philosophy, physiology, medicine, and social inquiry. Students learn that psychology is not common sense with vocabulary; it is a disciplined way to ask and test questions about behavior, mind, brain, and context.', 0),
  ('62c89f9b-7ced-4108-939d-9a89400e97d9', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'e2fec21a-d1aa-4bf0-818b-23a84da817bb', 'subtopic'::public.curated_course_node_type, 'Historical roots and systems', 'Students see how psychology''s founding schools shaped later debates about consciousness, behavior, cognition, emotion, and mental health.', 0),
  ('5fdca74d-2cd8-4587-b4ff-a6a8b5caee8c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '62c89f9b-7ced-4108-939d-9a89400e97d9', 'concept'::public.curated_course_node_type, 'Philosophical roots and early laboratories', null, 0),
  ('c6030a17-adac-4bbc-b76b-8b25f31d9efb', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '62c89f9b-7ced-4108-939d-9a89400e97d9', 'concept'::public.curated_course_node_type, 'Structuralism, functionalism, behaviorism, Gestalt, psychoanalysis, humanism', null, 1),
  ('2203ab08-9867-4538-9942-471427e7dbf6', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '62c89f9b-7ced-4108-939d-9a89400e97d9', 'concept'::public.curated_course_node_type, 'Cognitive revolution and contemporary psychological science', null, 2),
  ('2c50cec7-40b9-4972-b6a2-09f1c4b14b11', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'e2fec21a-d1aa-4bf0-818b-23a84da817bb', 'subtopic'::public.curated_course_node_type, 'Major perspectives in psychology', 'The field is plural because human behavior has many causes; students learn to use perspectives as tools rather than rival slogans.', 1),
  ('fc6f2f20-2201-4c5a-8f24-74953dbe3204', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2c50cec7-40b9-4972-b6a2-09f1c4b14b11', 'concept'::public.curated_course_node_type, 'Biological and evolutionary perspectives', null, 0),
  ('0ba0f993-fed2-4117-902b-d291bf98010f', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2c50cec7-40b9-4972-b6a2-09f1c4b14b11', 'concept'::public.curated_course_node_type, 'Cognitive, behavioral, and social-cultural perspectives', null, 1),
  ('7ebd52b2-bced-4d81-8be4-902470ec5dd5', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2c50cec7-40b9-4972-b6a2-09f1c4b14b11', 'concept'::public.curated_course_node_type, 'Clinical, developmental, and humanistic perspectives', null, 2),
  ('f6badcce-7e47-4c7e-bd38-a0e685598481', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'e2fec21a-d1aa-4bf0-818b-23a84da817bb', 'subtopic'::public.curated_course_node_type, 'Core questions of the discipline', 'Students begin with questions that organize the entire course and keep the survey coherent.', 2),
  ('8e198c33-9681-4dcc-bbc0-e22431a613d7', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f6badcce-7e47-4c7e-bd38-a0e685598481', 'concept'::public.curated_course_node_type, 'Nature and nurture', null, 0),
  ('f4f17cd4-0890-4823-aebc-12e38814daa8', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f6badcce-7e47-4c7e-bd38-a0e685598481', 'concept'::public.curated_course_node_type, 'Mind, brain, and behavior', null, 1),
  ('4709830b-73ea-4169-92f7-3b0160c9a7fe', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f6badcce-7e47-4c7e-bd38-a0e685598481', 'concept'::public.curated_course_node_type, 'Individual differences, culture, and human universals', null, 2),
  ('8388fec9-2d47-4392-97ae-ba4d1a8765c5', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Research Methods, Ethics, and Scientific Literacy', 'An effective introduction to psychology must teach students how psychologists know what they claim to know. This unit gives students the habits needed to evaluate evidence, recognize weak claims, and read psychological research responsibly.', 1),
  ('668865dd-8eca-4152-bb57-1e42537d97fc', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8388fec9-2d47-4392-97ae-ba4d1a8765c5', 'subtopic'::public.curated_course_node_type, 'Scientific method and research design', 'Students learn how hypotheses become testable studies and how design choices shape what can be concluded.', 0),
  ('f76762f9-da7d-48b9-982f-715e6422a668', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '668865dd-8eca-4152-bb57-1e42537d97fc', 'concept'::public.curated_course_node_type, 'Descriptive, correlational, experimental, and quasi-experimental designs', null, 0),
  ('5fe15604-8247-4e87-910a-4a6343ce27e1', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '668865dd-8eca-4152-bb57-1e42537d97fc', 'concept'::public.curated_course_node_type, 'Independent, dependent, and confounding variables', null, 1),
  ('2127b0ba-d07e-4834-9775-ae4bb21556a5', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '668865dd-8eca-4152-bb57-1e42537d97fc', 'concept'::public.curated_course_node_type, 'Sampling, random assignment, control, and comparison groups', null, 2),
  ('cbd728e6-ae19-4678-9b35-278c0ccb315e', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8388fec9-2d47-4392-97ae-ba4d1a8765c5', 'subtopic'::public.curated_course_node_type, 'Measurement and interpretation', 'Psychological concepts must be operationalized; students learn why measurement quality matters.', 1),
  ('9db167d9-ee36-4178-86fe-02164008bf48', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'cbd728e6-ae19-4678-9b35-278c0ccb315e', 'concept'::public.curated_course_node_type, 'Reliability and validity', null, 0),
  ('9cbc71f0-dd4d-4ae9-b909-de0424cf5c50', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'cbd728e6-ae19-4678-9b35-278c0ccb315e', 'concept'::public.curated_course_node_type, 'Effect size, statistical significance, and practical significance', null, 1),
  ('dc8faa5d-5ef1-454d-a266-93d1c9d262b1', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'cbd728e6-ae19-4678-9b35-278c0ccb315e', 'concept'::public.curated_course_node_type, 'Graphs, base rates, and common reasoning errors', null, 2),
  ('14ff297d-2841-422d-8884-5d098de3f01d', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8388fec9-2d47-4392-97ae-ba4d1a8765c5', 'subtopic'::public.curated_course_node_type, 'Ethics, replication, and open science', 'Students learn the ethical obligations of human and animal research and why transparency strengthens science.', 2),
  ('acaff82e-2c32-4730-838c-d2a8d4889065', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '14ff297d-2841-422d-8884-5d098de3f01d', 'concept'::public.curated_course_node_type, 'Informed consent, deception, debriefing, confidentiality, and IRB review', null, 0),
  ('42eed63d-a63d-4cde-88c5-3642e82ad24f', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '14ff297d-2841-422d-8884-5d098de3f01d', 'concept'::public.curated_course_node_type, 'APA ethics and responsible reporting', null, 1),
  ('c0c9abf1-6874-4370-a862-90cbe11a8e1c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '14ff297d-2841-422d-8884-5d098de3f01d', 'concept'::public.curated_course_node_type, 'Replication, preregistration, data sharing, and publication bias', null, 2),
  ('36cd68b0-73db-46ad-b0f6-4192d77e25f4', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Biological Bases of Behavior and Neuroscience', 'This unit gives students enough neuroscience to connect mind and behavior to biological systems without reducing psychological life to brain parts. The point is integration: nervous systems, bodies, environments, and behavior constantly interact.', 2),
  ('aa3ad7a5-792e-410a-98a0-ec2b9c9cfa77', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '36cd68b0-73db-46ad-b0f6-4192d77e25f4', 'subtopic'::public.curated_course_node_type, 'Neurons and neural communication', 'Students learn the basic language of the nervous system and how cells communicate.', 0),
  ('40a0085c-2c15-4f4e-a489-f394f1e47d99', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'aa3ad7a5-792e-410a-98a0-ec2b9c9cfa77', 'concept'::public.curated_course_node_type, 'Neurons, glia, action potentials, and synapses', null, 0),
  ('c9536e73-53c3-4caa-b2c5-47b4bd35b689', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'aa3ad7a5-792e-410a-98a0-ec2b9c9cfa77', 'concept'::public.curated_course_node_type, 'Neurotransmitters and receptor systems', null, 1),
  ('a453cf6a-cc19-4fa5-9432-95bb68824e94', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'aa3ad7a5-792e-410a-98a0-ec2b9c9cfa77', 'concept'::public.curated_course_node_type, 'Agonists, antagonists, and psychoactive substances', null, 2),
  ('8501d48c-344e-4e76-90f0-cc2817f918e9', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '36cd68b0-73db-46ad-b0f6-4192d77e25f4', 'subtopic'::public.curated_course_node_type, 'Brain structures and methods', 'Students connect brain regions and networks to behavior while learning how evidence is gathered.', 1),
  ('20accdb1-5313-436e-a7e4-63c4085070eb', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8501d48c-344e-4e76-90f0-cc2817f918e9', 'concept'::public.curated_course_node_type, 'Hindbrain, limbic system, cortex, and association areas', null, 0),
  ('b5ccb634-752b-40f2-a252-1da8f80b3858', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8501d48c-344e-4e76-90f0-cc2817f918e9', 'concept'::public.curated_course_node_type, 'fMRI, EEG, lesion studies, and neuropsychology', null, 1),
  ('6b656d6b-70b8-4d15-8545-76b5fc491a95', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8501d48c-344e-4e76-90f0-cc2817f918e9', 'concept'::public.curated_course_node_type, 'Localization, networks, and limits of brain imaging', null, 2),
  ('f423a460-a982-467d-aed0-c7460375c142', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '36cd68b0-73db-46ad-b0f6-4192d77e25f4', 'subtopic'::public.curated_course_node_type, 'Genes, hormones, and plasticity', 'Students examine biology as dynamic rather than destiny.', 2),
  ('edee6f26-1d67-4d34-bf49-c737273fe394', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f423a460-a982-467d-aed0-c7460375c142', 'concept'::public.curated_course_node_type, 'Behavioral genetics and heritability', null, 0),
  ('8ce5955f-6667-4e44-8445-ebafe00efd35', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f423a460-a982-467d-aed0-c7460375c142', 'concept'::public.curated_course_node_type, 'Endocrine system and stress physiology', null, 1),
  ('9109156c-1322-4b5c-afac-6214bd3049fa', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f423a460-a982-467d-aed0-c7460375c142', 'concept'::public.curated_course_node_type, 'Neuroplasticity, development, and experience', null, 2),
  ('2b324aa6-f096-4d57-9e14-2328263b9510', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Sensation, Perception, Consciousness, and Sleep', 'Students learn that experience is constructed. Sensory systems register information, but perception depends on attention, expectation, context, and the brain''s active interpretation of the world.', 3);
