  ('f2fa220e-8edb-4777-9981-8095288ba548', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'cafbb9fd-9641-4d35-8131-b87acea30d8c', 'concept'::public.curated_course_node_type, 'Sensory adaptation and signal detection', null, 2),
  ('c703fcaa-8572-4846-a071-bca975c757c6', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2b324aa6-f096-4d57-9e14-2328263b9510', 'subtopic'::public.curated_course_node_type, 'Perception and attention', 'Students explore how the mind organizes incomplete information into meaningful experience.', 1),
  ('187961ca-f8f5-42ba-8438-9485d401d592', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'c703fcaa-8572-4846-a071-bca975c757c6', 'concept'::public.curated_course_node_type, 'Gestalt principles and perceptual constancy', null, 0),
  ('b903390a-e74a-4d49-836c-76200157f085', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'c703fcaa-8572-4846-a071-bca975c757c6', 'concept'::public.curated_course_node_type, 'Depth, motion, and pattern recognition', null, 1),
  ('43e68ccb-d669-4c4f-84f0-7ac2e8a9e68c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'c703fcaa-8572-4846-a071-bca975c757c6', 'concept'::public.curated_course_node_type, 'Top-down processing, attention, and illusions', null, 2),
  ('591b095c-3ede-4b08-9993-f6125e275029', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2b324aa6-f096-4d57-9e14-2328263b9510', 'subtopic'::public.curated_course_node_type, 'Consciousness and sleep', 'Students examine ordinary and altered states as psychological and biological phenomena.', 2),
  ('1370ac5b-38b7-4c9e-a85b-b676067c1664', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '591b095c-3ede-4b08-9993-f6125e275029', 'concept'::public.curated_course_node_type, 'Sleep stages and circadian rhythms', null, 0),
  ('6ae6bf79-fa70-4e86-93bf-a5eff9671cf9', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '591b095c-3ede-4b08-9993-f6125e275029', 'concept'::public.curated_course_node_type, 'Dreaming, sleep disorders, and sleep health', null, 1),
  ('d0e4f4fd-5f06-4062-b9bb-fb6962817921', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '591b095c-3ede-4b08-9993-f6125e275029', 'concept'::public.curated_course_node_type, 'Hypnosis, meditation, drugs, and altered states', null, 2),
  ('f90ea908-a925-49a8-b2e9-90aeb0815567', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Learning, Conditioning, and Behavior Change', 'Learning theory explains how experience changes behavior. Students use this unit to understand habits, fears, skills, incentives, parenting, education, therapy, and behavior-change design.', 4),
  ('f5caabd0-47be-4ee6-91f0-172695031a56', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f90ea908-a925-49a8-b2e9-90aeb0815567', 'subtopic'::public.curated_course_node_type, 'Classical conditioning', 'Students learn how organisms associate stimuli and how those associations shape emotion and behavior.', 0),
  ('44b70c86-2efa-4506-b976-02271c793c09', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f5caabd0-47be-4ee6-91f0-172695031a56', 'concept'::public.curated_course_node_type, 'Acquisition, extinction, spontaneous recovery, generalization, and discrimination', null, 0),
  ('34fc70df-7336-4c6a-99e9-d79b2f4a2ae1', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f5caabd0-47be-4ee6-91f0-172695031a56', 'concept'::public.curated_course_node_type, 'Pavlov, Watson, fear learning, and evaluative conditioning', null, 1),
  ('a44c9cee-3601-4e38-97a8-0aafa1547998', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f5caabd0-47be-4ee6-91f0-172695031a56', 'concept'::public.curated_course_node_type, 'Applications to anxiety, advertising, and emotion', null, 2),
  ('9da75d88-9c63-489e-9ed9-c48928792d14', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f90ea908-a925-49a8-b2e9-90aeb0815567', 'subtopic'::public.curated_course_node_type, 'Operant conditioning', 'Students learn how consequences shape behavior over time.', 1),
  ('c128cc7c-2de2-4511-a1ca-b859cca8fe18', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '9da75d88-9c63-489e-9ed9-c48928792d14', 'concept'::public.curated_course_node_type, 'Reinforcement, punishment, shaping, and extinction', null, 0),
  ('ccc15a73-0be3-4341-addb-3bee102788c3', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '9da75d88-9c63-489e-9ed9-c48928792d14', 'concept'::public.curated_course_node_type, 'Schedules of reinforcement', null, 1),
  ('a0e98f53-3446-4fc2-aef5-669ea0b0e72c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '9da75d88-9c63-489e-9ed9-c48928792d14', 'concept'::public.curated_course_node_type, 'Behavior modification and applied behavior analysis', null, 2),
  ('f09df8c4-9af1-410c-b51f-606fc69a51ca', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f90ea908-a925-49a8-b2e9-90aeb0815567', 'subtopic'::public.curated_course_node_type, 'Observational and cognitive learning', 'Students see why learning is not only trial and error; people learn by watching, expecting, and interpreting.', 2),
  ('3c519f1a-686a-4b37-b3ef-dd813f7349d4', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f09df8c4-9af1-410c-b51f-606fc69a51ca', 'concept'::public.curated_course_node_type, 'Bandura and modeling', null, 0),
  ('9ef302f2-9ede-4d1c-8e21-e1f4268c9ebc', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f09df8c4-9af1-410c-b51f-606fc69a51ca', 'concept'::public.curated_course_node_type, 'Latent learning and cognitive maps', null, 1),
  ('4328492f-1067-4e1c-9cbe-33473e61b5ad', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f09df8c4-9af1-410c-b51f-606fc69a51ca', 'concept'::public.curated_course_node_type, 'Self-efficacy, feedback, and behavior change', null, 2),
  ('6df4fc17-86d3-48e2-8361-c6b77175eff5', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Memory, Thinking, Language, and Intelligence', 'This unit introduces the information-processing side of psychology while keeping it tied to everyday life: studying, eyewitness memory, judgment, language, testing, creativity, and decision-making.', 5),
  ('f5bdaaf5-42f3-444e-816f-84c186a3e534', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '6df4fc17-86d3-48e2-8361-c6b77175eff5', 'subtopic'::public.curated_course_node_type, 'Memory systems and forgetting', 'Students learn how memory is encoded, stored, retrieved, distorted, and reconstructed.', 0),
  ('75caf40d-f9d8-4c1f-a868-83ff0d6c3212', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f5bdaaf5-42f3-444e-816f-84c186a3e534', 'concept'::public.curated_course_node_type, 'Working memory and long-term memory', null, 0),
  ('63030d55-2025-49c7-924b-9090dc4265cf', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f5bdaaf5-42f3-444e-816f-84c186a3e534', 'concept'::public.curated_course_node_type, 'Encoding, retrieval cues, and consolidation', null, 1),
  ('bd039732-dd2a-4b06-a7ff-c7b159ce9339', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f5bdaaf5-42f3-444e-816f-84c186a3e534', 'concept'::public.curated_course_node_type, 'Forgetting, interference, false memories, and eyewitness testimony', null, 2),
  ('f55a0f99-e2f1-47e5-a110-5bdf5a0e2cac', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '6df4fc17-86d3-48e2-8361-c6b77175eff5', 'subtopic'::public.curated_course_node_type, 'Thinking and decision-making', 'Students examine how people solve problems and why judgment can be both powerful and biased.', 1),
  ('5a6f92e1-731b-467b-b348-a8bfc24510b0', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f55a0f99-e2f1-47e5-a110-5bdf5a0e2cac', 'concept'::public.curated_course_node_type, 'Concepts, prototypes, and schemas', null, 0),
  ('0c85e8eb-7f42-4461-906d-30bb77756cc6', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f55a0f99-e2f1-47e5-a110-5bdf5a0e2cac', 'concept'::public.curated_course_node_type, 'Heuristics and biases', null, 1),
  ('a7205330-68fe-422c-b37c-42933925e9bc', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'f55a0f99-e2f1-47e5-a110-5bdf5a0e2cac', 'concept'::public.curated_course_node_type, 'Problem solving, creativity, and expertise', null, 2),
  ('2964243f-3a90-42cc-ae4e-819efe2686c7', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '6df4fc17-86d3-48e2-8361-c6b77175eff5', 'subtopic'::public.curated_course_node_type, 'Language and intelligence', 'Students consider communication and ability as complex, culturally situated constructs.', 2),
  ('78cac0e6-885a-4d99-a4af-d0c9ca0d7ad1', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2964243f-3a90-42cc-ae4e-819efe2686c7', 'concept'::public.curated_course_node_type, 'Language development and structure', null, 0),
  ('32cd2b7c-fa68-4e44-be2e-74a8f0293e0c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2964243f-3a90-42cc-ae4e-819efe2686c7', 'concept'::public.curated_course_node_type, 'Psychometrics, IQ, and multiple abilities debates', null, 1),
  ('6b4e4ac4-0e63-4a4c-a671-dc4692fac899', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2964243f-3a90-42cc-ae4e-819efe2686c7', 'concept'::public.curated_course_node_type, 'Stereotype threat, test bias, and interpretation', null, 2),
  ('360f693f-3cee-4e7c-b03d-18e406d6a58f', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Development Across the Lifespan', 'Developmental psychology helps students understand change and continuity. This unit follows human development across the lifespan while showing how biology, culture, family, peers, institutions, and historical context shape lives.', 6),
  ('8e1da7c0-f554-4ad2-b94a-fc574ede147c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '360f693f-3cee-4e7c-b03d-18e406d6a58f', 'subtopic'::public.curated_course_node_type, 'Foundations of development', 'Students learn the core debates and methods used to study change over time.', 0);
