  ('2eb59a8c-f339-4292-858d-1c094dd403d3', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '360f693f-3cee-4e7c-b03d-18e406d6a58f', 'subtopic'::public.curated_course_node_type, 'Adulthood, aging, and end of life', 'Students consider adulthood as a period of continued development rather than a static endpoint.', 2),
  ('bbb8af8c-60a7-40d7-b418-3b4602aadaa9', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2eb59a8c-f339-4292-858d-1c094dd403d3', 'concept'::public.curated_course_node_type, 'Emerging and middle adulthood', null, 0),
  ('b0af1114-819d-4e04-9b65-ab36c8fe47e2', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2eb59a8c-f339-4292-858d-1c094dd403d3', 'concept'::public.curated_course_node_type, 'Cognitive aging, health, and social roles', null, 1),
  ('9b176454-a186-4ba4-93ee-16c528dbcad0', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '2eb59a8c-f339-4292-858d-1c094dd403d3', 'concept'::public.curated_course_node_type, 'Late adulthood, caregiving, death, and bereavement', null, 2),
  ('44141643-3947-47f5-a0a9-f64d04e90ca2', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Motivation, Emotion, Stress, and Health', 'This unit links psychology to everyday functioning. Students learn why people pursue goals, how emotions organize action, and how stress and behavior influence health.', 7),
