  ('4cb4323b-ce06-46d7-9b10-fad03fc278f2', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '200c2d87-e3f9-47c6-8734-81106d82b52c', 'concept'::public.curated_course_node_type, 'Drive reduction, incentives, and arousal', null, 0),
  ('fec3b5dc-0f98-461b-9096-702cab0f1b5c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '200c2d87-e3f9-47c6-8734-81106d82b52c', 'concept'::public.curated_course_node_type, 'Self-determination theory and intrinsic motivation', null, 1),
  ('d0f5d1fe-68b4-4b74-8ed0-bd1ee8b54a73', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '200c2d87-e3f9-47c6-8734-81106d82b52c', 'concept'::public.curated_course_node_type, 'Hunger, achievement, belonging, and meaning', null, 2),
  ('08a8e341-d8f4-4bf1-badf-dda17df41253', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '44141643-3947-47f5-a0a9-f64d04e90ca2', 'subtopic'::public.curated_course_node_type, 'Emotion and affective science', 'Students learn how emotion involves body, appraisal, expression, culture, and regulation.', 1),
  ('1f4b8587-9f81-41fa-b7be-3d143b66629c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '08a8e341-d8f4-4bf1-badf-dda17df41253', 'concept'::public.curated_course_node_type, 'James-Lange, Cannon-Bard, Schachter-Singer, and appraisal theories', null, 0),
