  ('d6f41f83-5e58-4bb4-9d8c-24378df95605', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '08a8e341-d8f4-4bf1-badf-dda17df41253', 'concept'::public.curated_course_node_type, 'Emotion regulation and wellbeing', null, 2),
  ('d1b6be95-8371-4533-9623-cb024573cb88', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '44141643-3947-47f5-a0a9-f64d04e90ca2', 'subtopic'::public.curated_course_node_type, 'Stress, coping, and health psychology', 'Students connect stress physiology and behavior to health outcomes and disparities.', 2),
  ('69e29de1-1124-4e62-abcb-e8785b8b8233', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'd1b6be95-8371-4533-9623-cb024573cb88', 'concept'::public.curated_course_node_type, 'General adaptation, appraisal, and coping', null, 0),
  ('cd91f81c-f381-4bd9-b2d4-10065a5b111d', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'd1b6be95-8371-4533-9623-cb024573cb88', 'concept'::public.curated_course_node_type, 'Psychoneuroimmunology and chronic stress', null, 1),
  ('4bab1ea5-19f1-4a94-bae0-59b231347c6c', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'd1b6be95-8371-4533-9623-cb024573cb88', 'concept'::public.curated_course_node_type, 'Health behavior, addiction, adherence, and prevention', null, 2),
  ('216e087c-4942-4ac9-9dfd-5e12b72c0b5f', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Personality and Individual Differences', 'Personality psychology asks why people differ in stable ways and how those differences develop, change, and matter. Students learn to compare theories and evaluate personality assessment carefully.', 8),
