  ('f594e1d1-f902-48e5-9574-d0831b72b5a2', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'c910a114-edcf-433e-a856-73d4868d7fed', 'concept'::public.curated_course_node_type, 'Psychoanalytic and neo-analytic theories', null, 0),
  ('67e00f56-3763-47ba-9c0e-a174096e90d0', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'c910a114-edcf-433e-a856-73d4868d7fed', 'concept'::public.curated_course_node_type, 'Humanistic and existential approaches', null, 1),
  ('768aa826-6232-48c1-9cbd-4a06484e7032', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'c910a114-edcf-433e-a856-73d4868d7fed', 'concept'::public.curated_course_node_type, 'Behavioral and social-cognitive theories', null, 2),
  ('e0577324-28aa-445e-9843-bbdf5b566180', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '216e087c-4942-4ac9-9dfd-5e12b72c0b5f', 'subtopic'::public.curated_course_node_type, 'Trait and biological approaches', 'Students examine personality as measurable individual differences with biological and environmental influences.', 1),
  ('3d3ce331-a5f5-4e1b-833a-5eab24783eda', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'e0577324-28aa-445e-9843-bbdf5b566180', 'concept'::public.curated_course_node_type, 'Big Five and trait taxonomy', null, 0),
  ('8e1e69a9-b265-46b0-ad1d-d02060d8b168', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'e0577324-28aa-445e-9843-bbdf5b566180', 'concept'::public.curated_course_node_type, 'Temperament, genetics, and biology', null, 1),
  ('47140b78-c603-4e00-b30c-0e09a54cb323', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', 'e0577324-28aa-445e-9843-bbdf5b566180', 'concept'::public.curated_course_node_type, 'Person-situation debate', null, 2),
