  ('eb1655d4-95d8-47fd-ba93-d842e04ecefe', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '473af2ff-ff98-489a-9be3-b30f222c51a3', 'concept'::public.curated_course_node_type, 'Self-report inventories and validity limits', null, 0),
  ('f41a7ef6-9586-4f9f-bdea-4daf791909cd', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '473af2ff-ff98-489a-9be3-b30f222c51a3', 'concept'::public.curated_course_node_type, 'Projective tests and controversies', null, 1),
  ('aa157134-1b5c-4cfc-a0f8-0603428d745e', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '473af2ff-ff98-489a-9be3-b30f222c51a3', 'concept'::public.curated_course_node_type, 'Self, identity, culture, and personality development', null, 2),
  ('8ba18dd7-afad-4e92-896b-591d3bc519a5', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', null, 'topic'::public.curated_course_node_type, 'Social Psychology, Culture, and Group Life', 'Social psychology shows that people are shaped by situations, relationships, groups, institutions, and culture. This unit gives students tools to understand influence, belonging, prejudice, cooperation, and conflict.', 9),
  ('053e76e5-6b3e-41ac-87ae-be42e996ae09', 'f6b7c8d9-0e1f-4a76-9b56-6c7d8e9f0a16', '8ba18dd7-afad-4e92-896b-591d3bc519a5', 'subtopic'::public.curated_course_node_type, 'Social cognition and attitudes', 'Students learn how people interpret themselves, others, and social situations.', 0),
