select
  'introduction-to-psychology',
  null,
  'Introduction to Psychology',
  'Introduction to Psychology',
  'This course introduces psychology as the scientific study of behavior, mind, brain, and social life. Students examine the field''s history, methods, biological foundations, sensation and perception, consciousness, learning, memory, cognition, development, motivation, emotion, personality, social behavior, psychological disorders, therapy, health, and applied psychology. The course emphasizes evidence, ethics, diversity, cultural context, and the practical value of psychological science.',
  $ipsyjson${"slug": "introduction-to-psychology", "title": "Introduction to Psychology", "description": "This course introduces psychology as the scientific study of behavior, mind, brain, and social life. Students examine the field's history, methods, biological foundations, sensation and perception, consciousness, learning, memory, cognition, development, motivation, emotion, personality, social behavior, psychological disorders, therapy, health, and applied psychology. The course emphasizes evidence, ethics, diversity, cultural context, and the practical value of psychological science.", "topics": [{"id": "e2fec21a-d1aa-4bf0-818b-23a84da817bb", "type": "topic", "title": "Psychology as a Science: History, Perspectives, and Big Questions", "description": "This opening unit frames psychology as a science that grew from philosophy, physiology, medicine, and social inquiry. Students learn that psychology is not common sense with vocabulary; it is a disciplined way to ask and test questions about behavior, mind, brain, and context.", "children": [{"id": "62c89f9b-7ced-4108-939d-9a89400e97d9", "type": "subtopic", "title": "Historical roots and systems", "children": [{"id": "5fdca74d-2cd8-4587-b4ff-a6a8b5caee8c", "type": "concept", "title": "Philosophical roots and early laboratories"}, {"id": "c6030a17-adac-4bbc-b76b-8b25f31d9efb", "type": "concept", "title": "Structuralism, functionalism, behaviorism, Gestalt, psychoanalysis, humanism"}, {"id": "2203ab08-9867-4538-9942-471427e7dbf6", "type": "concept", "title": "Cognitive revolution and contemporary psychological science"}], "description": "Students see how psychology's founding schools shaped later debates about consciousness, behavior, cognition, emotion, and mental health."}, {"id": "2c50cec7-40b9-4972-b6a2-09f1c4b14b11", "type": "subtopic", "title": "Major perspectives in psychology", "children": [{"id": "fc6f2f20-2201-4c5a-8f24-74953dbe3204", "type": "concept", "title": "Biological and evolutionary perspectives"}, {"id": "0ba0f993-fed2-4117-902b-d291bf98010f", "type": "concept", "title": "Cognitive, behavioral, and social-cultural perspectives"}, {"id": "7ebd52b2-bced-4d81-8be4-902470ec5dd5", "type": "concept", "title": "Clinical, developmental, and humanistic perspectives"}], "description": "The field is plural because human behavior has many causes; students learn to use perspectives as tools rather than rival slogans."}, {"id": "f6badcce-7e47-4c7e-bd38-a0e685598481", "type": "subtopic", "title": "Core questions of the discipline", "children": [{"id": "8e198c33-9681-4dcc-bbc0-e22431a613d7", "type": "concept", "title": "Nature and nurture"}, {"id": "f4f17cd4-0890-4823-aebc-12e38814daa8", "type": "concept", "title": "Mind, brain, and behavior"}, {"id": "4709830b-73ea-4169-92f7-3b0160c9a7fe", "type": "concept", "title": "Individual differences, culture, and human universals"}], "description": "Students begin with questions that organize the entire course and keep the survey coherent."}]}, {"id": "8388fec9-2d47-4392-97ae-ba4d1a8765c5", "type": "topic", "title": "Research Methods, Ethics, and Scientific Literacy", "description": "An effective introduction to psychology must teach students how psychologists know what they claim to know. This unit gives students the habits needed to evaluate evidence, recognize weak claims, and read psychological research responsibly.", "children": [{"id": "668865dd-8eca-4152-bb57-1e42537d97fc", "type": "subtopic", "title": "Scientific method and research design", "children": [{"id": "f76762f9-da7d-48b9-982f-715e6422a668", "type": "concept", "title": "Descriptive, correlational, experimental, and quasi-experimental designs"}, {"id": "5fe15604-8247-4e87-910a-4a6343ce27e1", "type": "concept", "title": "Independent, dependent, and confounding variables"}, {"id": "2127b0ba-d07e-4834-9775-ae4bb21556a5", "type": "concept", "title": "Sampling, random assignment, control, and comparison groups"}], "description": "Students learn how hypotheses become testable studies and how design choices shape what can be concluded."}, {"id": "cbd728e6-ae19-4678-9b35-278c0ccb315e", "type": "subtopic", "title": "Measurement and interpretation", "children": [{"id": "9db167d9-ee36-4178-86fe-02164008bf48", "type": "concept", "title": "Reliability and validity"}, {"id": "9cbc71f0-dd4d-4ae9-b909-de0424cf5c50", "type": "concept", "title": "Effect size, statistical significance, and practical significance"}, {"id": "dc8faa5d-5ef1-454d-a266-93d1c9d262b1", "type": "concept", "title": "Graphs, base rates, and common reasoning errors"}], "description": "Psychological concepts must be operationalized; students learn why measurement quality matters."}, {"id": "14ff297d-2841-422d-8884-5d098de3f01d", "type": "subtopic", "title": "Ethics, replication, and open science", "children": [{"id": "acaff82e-2c32-4730-838c-d2a8d4889065", "type": "concept", "title": "Informed consent, deception, debriefing, confidentiality, and IRB review"}, {"id": "42eed63d-a63d-4cde-88c5-3642e82ad24f", "type": "concept", "title": "APA ethics and responsible reporting"}, {"id": "c0c9abf1-6874-4370-a862-90cbe11a8e1c", "type": "concept", "title": "Replication, preregistration, data sharing, and publication bias"}], "description": "Students learn the ethical obligations of human and animal research and why transparency strengthens science."}]}, {"id": "36cd68b0-73db-46ad-b0f6-4192d77e25f4", "type": "topic", "title": "Biological Bases of Behavior and Neuroscience", "description": "This unit gives students enough neuroscience to connect mind and behavior to biological systems without reducing psychological life to brain parts. The point is integration: nervous systems, bodies, environments, and behavior constantly interact.", "children": [{"id": "aa3ad7a5-792e-410a-98a0-ec2b9c9cfa77", "type": "subtopic", "title": "Neurons and neural communication", "children": [{"id": "40a0085c-2c15-4f4e-a489-f394f1e47d99", "type": "concept", "title": "Neurons, glia, action potentials, and synapses"}, {"id": "c9536e73-53c3-4caa-b2c5-47b4bd35b689", "type": "concept", "title": "Neurotransmitters and receptor systems"}, {"id": "a453cf6a-cc19-4fa5-9432-95bb68824e94", "type": "concept", "title": "Agonists, antagonists, and psychoactive substances"}], "description": "Students learn the basic language of the nervous system and how cells communicate."}, {"id": "8501d48c-344e-4e76-90f0-cc2817f918e9", "type": "subtopic", "title": "Brain structures and methods", "children": [{"id": "20accdb1-5313-436e-a7e4-63c4085070eb", "type": "concept", "title": "Hindbrain, limbic system, cortex, and association areas"}, {"id": "b5ccb634-752b-40f2-a252-1da8f80b3858", "type": "concept", "title": "fMRI, EEG, lesion studies, and neuropsychology"}, {"id": "6b656d6b-70b8-4d15-8545-76b5fc491a95", "type": "concept", "title": "Localization, networks, and limits of brain imaging"}], "description": "Students connect brain regions and networks to behavior while learning how evidence is gathered."}, {"id": "f423a460-a982-467d-aed0-c7460375c142", "type": "subtopic", "title": "Genes, hormones, and plasticity", "children": [{"id": "edee6f26-1d67-4d34-bf49-c737273fe394", "type": "concept", "title": "Behavioral genetics and heritability"}, {"id": "8ce5955f-6667-4e44-8445-ebafe00efd35", "type": "concept", "title": "Endocrine system and stress physiology"}, {"id": "9109156c-1322-4b5c-afac-6214bd3049fa", "type": "concept", "title": "Neuroplasticity, development, and experience"}], "description": "Students examine biology as dynamic rather than destiny."}]}, {"id": "2b324aa6-f096-4d57-9e14-2328263b9510", "type": "topic", "title": "Sensation, Perception, Consciousness, and Sleep", "description": "Students learn that experience is constructed. Sensory systems register information, but perception depends on attention, expectation, context, and the brain's active interpretation of the world.", "children": [{"id": "cafbb9fd-9641-4d35-8131-b87acea30d8c", "type": "subtopic", "title": "Sensation and sensory systems", "children": [{"id": "4adc1de4-5238-4135-a97f-1df8db126ed1", "type": "concept", "title": "Absolute and difference thresholds"}, {"id": "fa81be61-fa1e-428d-b8f4-92c1e26e4a10", "type": "concept", "title": "Vision, audition, touch, taste, and smell"}, {"id": "f2fa220e-8edb-4777-9981-8095288ba548", "type": "concept", "title": "Sensory adaptation and signal detection"}], "description": "Students learn how physical energy becomes psychological experience."}, {"id": "c703fcaa-8572-4846-a071-bca975c757c6", "type": "subtopic", "title": "Perception and attention", "children": [{"id": "187961ca-f8f5-42ba-8438-9485d401d592", "type": "concept", "title": "Gestalt principles and perceptual constancy"}, {"id": "b903390a-e74a-4d49-836c-76200157f085", "type": "concept", "title": "Depth, motion, and pattern recognition"}, {"id": "43e68ccb-d669-4c4f-84f0-7ac2e8a9e68c", "type": "concept", "title": "Top-down processing, attention, and illusions"}], "description": "Students explore how the mind organizes incomplete information into meaningful experience."}, {"id": "591b095c-3ede-4b08-9993-f6125e275029", "type": "subtopic", "title": "Consciousness and sleep", "children": [{"id": "1370ac5b-38b7-4c9e-a85b-b676067c1664", "type": "concept", "title": "Sleep stages and circadian rhythms"}, {"id": "6ae6bf79-fa70-4e86-93bf-a5eff9671cf9", "type": "concept", "title": "Dreaming, sleep disorders, and sleep health"}, {"id": "d0e4f4fd-5f06-4062-b9bb-fb6962817921", "type": "concept", "title": "Hypnosis, meditation, drugs, and altered states"}], "description": "Students examine ordinary and altered states as psychological and biological phenomena."}]}, {"id": "f90ea908-a925-49a8-b2e9-90aeb0815567", "type": "topic", "title": "Learning, Conditioning, and Behavior Change", "description": "Learning theory explains how experience changes behavior. Students use this unit to understand habits, fears, skills, incentives, parenting, education, therapy, and behavior-change design.", "children": [{"id": "f5caabd0-47be-4ee6-91f0-172695031a56", "type": "subtopic", "title": "Classical conditioning", "children": [{"id": "44b70c86-2efa-4506-b976-02271c793c09", "type": "concept", "title": "Acquisition, extinction, spontaneous recovery, generalization, and discrimination"}, {"id": "34fc70df-7336-4c6a-99e9-d79b2f4a2ae1", "type": "concept", "title": "Pavlov, Watson, fear learning, and evaluative conditioning"}, {"id": "a44c9cee-3601-4e38-97a8-0aafa1547998", "type": "concept", "title": "Applications to anxiety, advertising, and emotion"}], "description": "Students learn how organisms associate stimuli and how those associations shape emotion and behavior."}, {"id": "9da75d88-9c63-489e-9ed9-c48928792d14", "type": "subtopic", "title": "Operant conditioning", "children": [{"id": "c128cc7c-2de2-4511-a1ca-b859cca8fe18", "type": "concept", "title": "Reinforcement, punishment, shaping, and extinction"}, {"id": "ccc15a73-0be3-4341-addb-3bee102788c3", "type": "concept", "title": "Schedules of reinforcement"}, {"id": "a0e98f53-3446-4fc2-aef5-669ea0b0e72c", "type": "concept", "title": "Behavior modification and applied behavior analysis"}], "description": "Students learn how consequences shape behavior over time."}, {"id": "f09df8c4-9af1-410c-b51f-606fc69a51ca", "type": "subtopic", "title": "Observational and cognitive learning", "children": [{"id": "3c519f1a-686a-4b37-b3ef-dd813f7349d4", "type": "concept", "title": "Bandura and modeling"}, {"id": "9ef302f2-9ede-4d1c-8e21-e1f4268c9ebc", "type": "concept", "title": "Latent learning and cognitive maps"}, {"id": "4328492f-1067-4e1c-9cbe-33473e61b5ad", "type": "concept", "title": "Self-efficacy, feedback, and behavior change"}], "description": "Students see why learning is not only trial and error; people learn by watching, expecting, and interpreting."}]}, {"id": "6df4fc17-86d3-48e2-8361-c6b77175eff5", "type": "topic", "title": "Memory, Thinking, Language, and Intelligence", "description": "This unit introduces the information-processing side of psychology while keeping it tied to everyday life: studying, eyewitness memory, judgment, language, testing, creativity, and decision-making.", "children": [{"id": "f5bdaaf5-42f3-444e-816f-84c186a3e534", "type": "subtopic", "title": "Memory systems and forgetting", "children": [{"id": "75caf40d-f9d8-4c1f-a868-83ff0d6c3212", "type": "concept", "title": "Working memory and long-term memory"}, {"id": "63030d55-2025-49c7-924b-9090dc4265cf", "type": "concept", "title": "Encoding, retrieval cues, and consolidation"}, {"id": "bd039732-dd2a-4b06-a7ff-c7b159ce9339", "type": "concept", "title": "Forgetting, interference, false memories, and eyewitness testimony"}], "description": "Students learn how memory is encoded, stored, retrieved, distorted, and reconstructed."}, {"id": "f55a0f99-e2f1-47e5-a110-5bdf5a0e2cac", "type": "subtopic", "title": "Thinking and decision-making", "children": [{"id": "5a6f92e1-731b-467b-b348-a8bfc24510b0", "type": "concept", "title": "Concepts, prototypes, and schemas"}, {"id": "0c85e8eb-7f42-4461-906d-30bb77756cc6", "type": "concept", "title": "Heuristics and biases"}, {"id": "a7205330-68fe-422c-b37c-42933925e9bc", "type": "concept", "title": "Problem solving, creativity, and expertise"}], "description": "Students examine how people solve problems and why judgment can be both powerful and biased."}, {"id": "2964243f-3a90-42cc-ae4e-819efe2686c7", "type": "subtopic", "title": "Language and intelligence", "children": [{"id": "78cac0e6-885a-4d99-a4af-d0c9ca0d7ad1", "type": "concept", "title": "Language development and structure"}, {"id": "32cd2b7c-fa68-4e44-be2e-74a8f0293e0c", "type": "concept", "title": "Psychometrics, IQ, and multiple abilities debates"}, {"id": "6b4e4ac4-0e63-4a4c-a671-dc4692fac899", "type": "concept", "title": "Stereotype threat, test bias, and interpretation"}], "description": "Students consider communication and ability as complex, culturally situated constructs."}]}, {"id": "360f693f-3cee-4e7c-b03d-18e406d6a58f", "type": "topic", "title": "Development Across the Lifespan", "description": "Developmental psychology helps students understand change and continuity. This unit follows human development across the lifespan while showing how biology, culture, family, peers, institutions, and historical context shape lives.", "children": [{"id": "8e1da7c0-f554-4ad2-b94a-fc574ede147c", "type": "subtopic", "title": "Foundations of development", "children": [{"id": "60762b84-a6ec-4c3f-b2d3-70ecef598127", "type": "concept", "title": "Nature, nurture, and interaction"}, {"id": "3c7e8db3-8eb6-4385-bc51-3f046de21375", "type": "concept", "title": "Cross-sectional, longitudinal, and cohort designs"}, {"id": "edf6a9ee-22f4-4a4f-9b80-193f6437dd78", "type": "concept", "title": "Sensitive periods, plasticity, and context"}], "description": "Students learn the core debates and methods used to study change over time."}, {"id": "7d1608b2-1061-4b5f-906b-b79c07fd998c", "type": "subtopic", "title": "Infancy, childhood, and adolescence", "children": [{"id": "19c0bcf1-cc50-4d63-90bc-4c5b923879f6", "type": "concept", "title": "Piaget, Vygotsky, and cognitive development"}, {"id": "6d220d23-badb-4ced-a857-3976b7847519", "type": "concept", "title": "Attachment, temperament, and emotion regulation"}, {"id": "80549cae-039b-4014-8215-94e7d7aa4076", "type": "concept", "title": "Adolescence, identity, peers, and risk"}], "description": "Students examine early growth in cognition, attachment, identity, and social relationships."}, {"id": "2eb59a8c-f339-4292-858d-1c094dd403d3", "type": "subtopic", "title": "Adulthood, aging, and end of life", "children": [{"id": "bbb8af8c-60a7-40d7-b418-3b4602aadaa9", "type": "concept", "title": "Emerging and middle adulthood"}, {"id": "b0af1114-819d-4e04-9b65-ab36c8fe47e2", "type": "concept", "title": "Cognitive aging, health, and social roles"}, {"id": "9b176454-a186-4ba4-93ee-16c528dbcad0", "type": "concept", "title": "Late adulthood, caregiving, death, and bereavement"}], "description": "Students consider adulthood as a period of continued development rather than a static endpoint."}]}, {"id": "44141643-3947-47f5-a0a9-f64d04e90ca2", "type": "topic", "title": "Motivation, Emotion, Stress, and Health", "description": "This unit links psychology to everyday functioning. Students learn why people pursue goals, how emotions organize action, and how stress and behavior influence health.", "children": [{"id": "200c2d87-e3f9-47c6-8734-81106d82b52c", "type": "subtopic", "title": "Motivation and goal pursuit", "children": [{"id": "4cb4323b-ce06-46d7-9b10-fad03fc278f2", "type": "concept", "title": "Drive reduction, incentives, and arousal"}, {"id": "fec3b5dc-0f98-461b-9096-702cab0f1b5c", "type": "concept", "title": "Self-determination theory and intrinsic motivation"}, {"id": "d0f5d1fe-68b4-4b74-8ed0-bd1ee8b54a73", "type": "concept", "title": "Hunger, achievement, belonging, and meaning"}], "description": "Students study biological, psychological, and social drivers of behavior."}, {"id": "08a8e341-d8f4-4bf1-badf-dda17df41253", "type": "subtopic", "title": "Emotion and affective science", "children": [{"id": "1f4b8587-9f81-41fa-b7be-3d143b66629c", "type": "concept", "title": "James-Lange, Cannon-Bard, Schachter-Singer, and appraisal theories"}, {"id": "8d2671bf-5cb3-426e-bacf-08a0a5c93dca", "type": "concept", "title": "Facial expression and culture"}, {"id": "d6f41f83-5e58-4bb4-9d8c-24378df95605", "type": "concept", "title": "Emotion regulation and wellbeing"}], "description": "Students learn how emotion involves body, appraisal, expression, culture, and regulation."}, {"id": "d1b6be95-8371-4533-9623-cb024573cb88", "type": "subtopic", "title": "Stress, coping, and health psychology", "children": [{"id": "69e29de1-1124-4e62-abcb-e8785b8b8233", "type": "concept", "title": "General adaptation, appraisal, and coping"}, {"id": "cd91f81c-f381-4bd9-b2d4-10065a5b111d", "type": "concept", "title": "Psychoneuroimmunology and chronic stress"}, {"id": "4bab1ea5-19f1-4a94-bae0-59b231347c6c", "type": "concept", "title": "Health behavior, addiction, adherence, and prevention"}], "description": "Students connect stress physiology and behavior to health outcomes and disparities."}]}, {"id": "216e087c-4942-4ac9-9dfd-5e12b72c0b5f", "type": "topic", "title": "Personality and Individual Differences", "description": "Personality psychology asks why people differ in stable ways and how those differences develop, change, and matter. Students learn to compare theories and evaluate personality assessment carefully.", "children": [{"id": "c910a114-edcf-433e-a856-73d4868d7fed", "type": "subtopic", "title": "Major personality theories", "children": [{"id": "f594e1d1-f902-48e5-9574-d0831b72b5a2", "type": "concept", "title": "Psychoanalytic and neo-analytic theories"}, {"id": "67e00f56-3763-47ba-9c0e-a174096e90d0", "type": "concept", "title": "Humanistic and existential approaches"}, {"id": "768aa826-6232-48c1-9cbd-4a06484e7032", "type": "concept", "title": "Behavioral and social-cognitive theories"}], "description": "Students learn how different traditions explain enduring patterns of thought, feeling, and behavior."}, {"id": "e0577324-28aa-445e-9843-bbdf5b566180", "type": "subtopic", "title": "Trait and biological approaches", "children": [{"id": "3d3ce331-a5f5-4e1b-833a-5eab24783eda", "type": "concept", "title": "Big Five and trait taxonomy"}, {"id": "8e1e69a9-b265-46b0-ad1d-d02060d8b168", "type": "concept", "title": "Temperament, genetics, and biology"}, {"id": "47140b78-c603-4e00-b30c-0e09a54cb323", "type": "concept", "title": "Person-situation debate"}], "description": "Students examine personality as measurable individual differences with biological and environmental influences."}, {"id": "473af2ff-ff98-489a-9be3-b30f222c51a3", "type": "subtopic", "title": "Assessment, culture, and identity", "children": [{"id": "eb1655d4-95d8-47fd-ba93-d842e04ecefe", "type": "concept", "title": "Self-report inventories and validity limits"}, {"id": "f41a7ef6-9586-4f9f-bdea-4daf791909cd", "type": "concept", "title": "Projective tests and controversies"}, {"id": "aa157134-1b5c-4cfc-a0f8-0603428d745e", "type": "concept", "title": "Self, identity, culture, and personality development"}], "description": "Students learn why personality assessment requires validity, interpretation, and cultural humility."}]}, {"id": "8ba18dd7-afad-4e92-896b-591d3bc519a5", "type": "topic", "title": "Social Psychology, Culture, and Group Life", "description": "Social psychology shows that people are shaped by situations, relationships, groups, institutions, and culture. This unit gives students tools to understand influence, belonging, prejudice, cooperation, and conflict.", "children": [{"id": "053e76e5-6b3e-41ac-87ae-be42e996ae09", "type": "subtopic", "title": "Social cognition and attitudes", "children": [{"id": "d95e9fb6-52a8-49d8-8d01-2532de75a093", "type": "concept", "title": "Attribution theory and attribution errors"}, {"id": "633d2b86-4be1-46c8-bf4a-cb09bddb6146", "type": "concept", "title": "Attitudes, persuasion, and cognitive dissonance"}, {"id": "ae8d2a43-22f3-4f64-8691-cfc2b90e3d4b", "type": "concept", "title": "Self-concept, identity, and impression formation"}], "description": "Students learn how people interpret themselves, others, and social situations."}, {"id": "b46cbb43-a5dc-4e1d-8290-8144d901035f", "type": "subtopic", "title": "Social influence and groups", "children": [{"id": "72221031-4882-4647-8dd1-29229b14f149", "type": "concept", "title": "Conformity, obedience, and compliance"}, {"id": "f36179c7-6075-40c4-b3cc-5395ad4b9ff1", "type": "concept", "title": "Group polarization and groupthink"}, {"id": "c290e527-446c-4633-9ceb-4ccccfb68872", "type": "concept", "title": "Leadership, cooperation, and social loafing"}], "description": "Students examine the power of norms, authority, roles, and group dynamics."}, {"id": "9376f089-d0b7-4b3a-ab99-e3e4729ead4c", "type": "subtopic", "title": "Prejudice, relationships, and culture", "children": [{"id": "e3f9686c-1fb8-47d9-891f-6c33d7c187c0", "type": "concept", "title": "Stereotyping, prejudice, discrimination, and implicit bias"}, {"id": "8042f36e-fcba-48b3-a93f-2a21d1e81ae7", "type": "concept", "title": "Attraction, attachment, prosocial behavior, and aggression"}, {"id": "6c415daa-f622-429f-b63e-3e32a6d648c0", "type": "concept", "title": "Culture, diversity, and cross-cultural psychology"}], "description": "Students connect interpersonal life to social structure and cultural context."}]}, {"id": "9f9131dc-d98c-46ad-93af-236b8a172994", "type": "topic", "title": "Psychological Disorders, Therapy, and Mental Health", "description": "This unit gives students mental health literacy without pretending that an introductory course trains diagnosis. Students learn major categories, evidence-based care principles, stigma reduction, and when professional help is needed.", "children": [{"id": "88048dcd-e669-4104-81a9-b0e81ae950fb", "type": "subtopic", "title": "Understanding psychological disorders", "children": [{"id": "acd4fc0c-3be2-41bc-8d62-8e8c1f135c0f", "type": "concept", "title": "Biopsychosocial model"}, {"id": "cf186eeb-3ba4-4952-bc2d-7021513e2b06", "type": "concept", "title": "DSM-5-TR overview and limits"}, {"id": "cb089a8c-77dd-4893-b26f-2dcfbbb45e40", "type": "concept", "title": "Stigma, recovery, and person-centered language"}], "description": "Students learn how distress, impairment, culture, and context shape definitions of disorder."}, {"id": "5ac9c4ca-6899-4fb6-bd10-3a742c47708b", "type": "subtopic", "title": "Major disorder families", "children": [{"id": "0a97c7c0-7fe4-452e-b4cb-136276ad41db", "type": "concept", "title": "Anxiety, OCD, trauma, depressive, and bipolar disorders"}, {"id": "613b55ae-1fb6-4084-a93c-4423e8e8bebd", "type": "concept", "title": "Schizophrenia spectrum and personality disorders"}, {"id": "12b814fa-e59b-4958-b8d3-f3f7cbdd0215", "type": "concept", "title": "Eating, substance-related, neurodevelopmental, and neurocognitive disorders"}], "description": "Students survey common and serious conditions while focusing on patterns rather than memorizing criteria."}, {"id": "f8b2a1ae-ce95-4840-aa88-6d99c301c934", "type": "subtopic", "title": "Therapy and evidence-based care", "children": [{"id": "ab021634-2532-48cc-b2cc-87a5f78f4cf5", "type": "concept", "title": "Psychodynamic, humanistic, behavioral, CBT, family, and group approaches"}, {"id": "95f21d48-8de2-4e56-86df-9c321f609642", "type": "concept", "title": "Medication, combined treatment, and stepped care"}, {"id": "ec2e5659-dbbf-41af-a5f2-a05eef99fcc0", "type": "concept", "title": "Prevention, crisis support, and access to care"}], "description": "Students learn how treatment approaches differ and what it means for care to be evidence-based."}]}, {"id": "cfc88283-6f4e-46b9-876a-89ba123a5e8a", "type": "topic", "title": "Applied Psychology, Careers, and Future Directions", "description": "The capstone unit helps students integrate the course and see psychology as both a scientific discipline and a practical toolkit for understanding real-world problems.", "children": [{"id": "9909e5e9-02a8-4625-a1b5-ab63925c2291", "type": "subtopic", "title": "Applied psychology domains", "children": [{"id": "cec81f3a-cbae-4371-9353-7c5bba48b315", "type": "concept", "title": "Educational, industrial-organizational, health, forensic, and community psychology"}, {"id": "b5e4044c-7558-451b-bc17-a6a46fbcfac7", "type": "concept", "title": "Human factors, design, and technology"}, {"id": "fd004ce8-c3d8-4ff3-b10f-694d2765c74e", "type": "concept", "title": "Behavioral science in policy and public health"}], "description": "Students learn how psychological science informs work far beyond therapy."}, {"id": "33ffb348-f3ef-4479-b78d-ba46acf8445d", "type": "subtopic", "title": "Careers, ethics, and professional pathways", "children": [{"id": "d606d5c4-c4c2-47fc-99e7-a0656dc2f87c", "type": "concept", "title": "BA/BS pathways and transferable skills"}, {"id": "75b1c2fd-71ed-4d05-afb8-f7a7d4753971", "type": "concept", "title": "Graduate routes and licensure boundaries"}, {"id": "deaeeae3-04ad-4c57-9de6-b94f8fbd635f", "type": "concept", "title": "Ethics, diversity, and professional responsibility"}], "description": "Students see the difference between psychology majors, graduate training, research careers, and licensed practice."}, {"id": "e66e6f12-0a9e-4e03-834f-5786d9b90c1a", "type": "subtopic", "title": "Future directions and integrative thinking", "children": [{"id": "85c68f85-ce0a-4222-9e33-7ff3dcb1f538", "type": "concept", "title": "AI, digital mental health, and technology ethics"}, {"id": "8de98b44-fd1c-43b9-b7b0-8eb17e6c934d", "type": "concept", "title": "Open science, reproducibility, and public trust"}, {"id": "41ba7efe-1f0a-447a-898f-fcf8dda59835", "type": "concept", "title": "Integrating biological, cognitive, social, developmental, and cultural levels"}], "description": "Students connect course themes to emerging questions and their own learning."}]}], "dbBacked": true}$ipsyjson$::jsonb,
  true,
